# port scan plugin
yakit.AutoInitYakit()

/*
本插件定义的函数主要用于端口扫描的额外扩展

函数定义如下：
func(result *fp.MatchResult)

// 详细结构体定义与内容见模版结尾
// 这里最关键的是，如果对扫描出的结果有疑问，需要对 MatchResult 进行修改，应该直接
// 对变量.Field 进行修改。

DEMO:

handle = func(result) {
    if result.Fingerprint != nil {
        if result.Port == 80 && result.GetServiceName() == "" {
            result.Fingerprint.ServiceName = "http"
        }
    }
}

*/
checkList = []

checkBroker = func(host, port){
    log.info("正在检测Broker未授权！-----------------------------")
    payload := "AAAAyQAAALF7ImNvZGUiOjI1LCJleHRGaWVsZHMiOnsiQWNjZXNzS2V5Ijoicm9ja2V0bXEyIiwiU2lnbmF0dXJlIjoiK3pkUmRVdWF6aVNRa0hVVXFkcnR3ZzFGOGprPSJ9LCJmbGFnIjowLCJsYW5ndWFnZSI6IkpBVkEiLCJvcGFxdWUiOjAsInNlcmlhbGl6ZVR5cGVDdXJyZW50UlBDIjoiSlNPTiIsInZlcnNpb24iOjQzM310ZXN0X2tleT10ZXN0X3ZhbHVlCg=="
   finger = [`"code":0`,`serializeTypeCurrentRPC`]
    mqClient, err = tcp.Connect(host, port, tcp.clientTimeout(5)) 
    if err != nil{
        return
    }
    package =make([]uint8,1024,1024)
    wlen, err = mqClient.Write(codec.DecodeBase64(payload)~)
    if err != nil{
        return
    }
    rlen, err = mqClient.Read(package)
    if err != nil{
        return
    }
    mqClient.Close()
    if str.Contains(string(package),finger[0]) && str.Contains(string(package),finger[1]){
        risk.NewRisk(
            mqClient.RemoteAddr().String(),
            risk.payload(payload),
            risk.severity("high"),
            risk.title("rocketmq broker未授权CVE-2023-33246"),
            risk.request(payload),
            risk.response(string(package)),
            risk.description("当RocketMQ多个组件，包括NameServer、Broker和Controller，都暴露在外网，并且缺乏有效的身份认证机制，那么攻击者可以利用更新配置功能，以RocketMQ运行的系统用户身份执行命令。"),
            risk.solution("1、在conf/broker.conf中针对Broker服务添加身份认证，确保只有授权用户才能访问和操作RocketMQ的消息队列。2、使用RocketMQ 4.x版本的用户升级至4.9.6或以上版本。使用RocketMQ 5.x版本的用户升级至5.1.1或以上版本"),
            risk.type("unauth"),
            risk.typeVerbose("未授权")
        )
    }
    log.info("Broker未授权检测完成！-----------------------------")
    return
}

checkNamesrv = func(host, port){
    log.info("正在检测Namesrv未授权！-----------------------------")
    payload := "AAAA0AAAALJ7ImNvZGUiOjMxOCwiZXh0RmllbGRzIjp7IkFjY2Vzc0tleSI6InJvY2tldG1xMiIsIlNpZ25hdHVyZSI6ImNHSmpxMUZCTSs0VUJsUnNORE50azBVOW5EMD0ifSwiZmxhZyI6MCwibGFuZ3VhZ2UiOiJKQVZBIiwib3BhcXVlIjowLCJzZXJpYWxpemVUeXBlQ3VycmVudFJQQyI6IkpTT04iLCJ2ZXJzaW9uIjo0MzV9dGhpc19pc19rZXk9dGhpc19pc192YWx1ZQo="
   finger = [`"code":0`,`serializeTypeCurrentRPC`]
    mqClient, err = tcp.Connect(host, port, tcp.clientTimeout(5)) 
    if err != nil{
        return
    }
    package =make([]uint8,1024,1024)
    wlen, err = mqClient.Write(codec.DecodeBase64(payload)~)
    if err != nil{
        return
    }
    rlen, err = mqClient.Read(package)
    if err != nil{
        return
    }
    mqClient.Close()
    if str.Contains(string(package),finger[0]) && str.Contains(string(package),finger[1]){
        risk.NewRisk(
            mqClient.RemoteAddr().String(),
            risk.payload(payload),
            risk.severity("high"),
            risk.title("rocketmq Namesrv未授权 CVE-2023-37582"),
            risk.request(payload),
            risk.response(string(package)),
            risk.description("当RocketMQ的NameServer组件暴露在外网时，并且缺乏有效的身份认证机制，那么攻击者可以利用更新配置功能，以RocketMQ运行的系统用户身份执行命令。"),
            risk.solution("1、添加身份认证机制，确保只有授权用户才能访问和操作RocketMQ的消息队列。2、使用RocketMQ 4.x版本的用户升级至4.9.7或以上版本。使用RocketMQ 5.x版本的用户升级至5.1.2或以上版本"),
            risk.type("unauth"),
            risk.typeVerbose("未授权")
        )
    }
    log.info("Namesrv未授权检测完成！-----------------------------")
    return
}
checkList = append(checkList,checkBroker)
checkList = append(checkList,checkNamesrv)

handle = func(result /* *fp.MatchResult */) {
    // handle match result
    if !result.IsOpen(){
        return
    }
    if len(result.Fingerprint.HttpFlows) == 0{
        wg := sync.NewSizedWaitGroup(10)
        for _, f = range checkList{
            f := f
            wg.Add()
            go func{
                defer wg.Done()
                f(result.Target,result.Port)
            }
        }
        wg.Wait()
    }
    log.info("%v rocketmq未授权插件检测完成！-----------------------------",result.Target)
}

/*
